const item = $input.first().json.body || $input.first().json;

const staffId = item.staffId || item.id || 101;
const staffName = item.staffName || 'Domestic Staff';
const staffType = item.staffType || 'MAID'; // MAID, DRIVER, COOK, CLEANER, ELECTRICIAN, PLUMBER, GARDENER, SECURITY_GUARD
const phone = item.phone || '+91 98765 00000';
const verificationStatus = item.verificationStatus || 'PENDING'; // VERIFIED, PENDING, REJECTED, SUSPENDED
const govtIdType = item.govtIdType || 'AADHAAR';
const govtIdNumber = item.govtIdNumber || 'XXXX-XXXX-1234';
const assignedFlats = item.assignedFlats || 'A-402, B-102';
const checkInTime = item.checkInTime || new Date().toISOString();
const checkOutTime = item.checkOutTime || null;
const entryMethod = item.verificationMethod || item.entryMethod || 'BIOMETRIC_FINGERPRINT';
const rating = item.rating ?? 4.5;

const prompt = `You are the Society Registrar and Domestic Staff Security Compliance Auditor for Mana Community Society.
Perform a security and KYC compliance audit for the following domestic worker check-in or credential record.

Staff Profile & Attendance Record:
- Staff ID: ${staffId}
- Name: ${staffName} (${staffType})
- Contact: ${phone}
- Verification Status: ${verificationStatus}
- Government ID: ${govtIdType} (${govtIdNumber})
- Assigned Household Flats: ${assignedFlats}
- Check-In Timestamp: ${checkInTime}
- Check-Out Timestamp: ${checkOutTime || 'Currently on-site'}
- Entry Gate Verification Method: ${entryMethod}
- Society Peer Rating: ${rating} / 5.0

Compliance Review Mandates:
1. Audit Police KYC & Background Verification compliance (VERIFIED_PASS, CONDITIONAL_30_DAY_GRACE, BLOCKED_UNVERIFIED).
2. Time-of-Entry Anomaly Check: Flag suspicious off-hours check-ins (e.g. domestic maid entering between 10:00 PM and 5:00 AM without emergency flat owner authorization).
3. Multi-Flat Access Authorization: Verify if assigned flat coverage matches typical staff capacity.
4. Determine Gate Access Verdict (PERMIT_ENTRY, PROCEED_WITH_WARNING, HOLD_AT_SECURITY_POST).
5. Formulate resident employer safety briefing.

Respond ONLY with a valid JSON object matching this exact schema:
{
  "accessVerdict": "PERMIT_ENTRY" | "PROCEED_WITH_WARNING" | "HOLD_AT_SECURITY_POST",
  "kycComplianceGrade": "FULL_COMPLIANCE" | "PROVISIONAL_GRACE" | "POLICE_VERIFICATION_DEFICIT" | "HIGH_RISK_SUSPENDED",
  "curfewAnomaly": boolean,
  "curfewNotes": string,
  "safetyScore": number,
  "securityOfficerAction": "Actionable order for on-duty security guard",
  "employerNotice": "Direct advisory text for the flat owners employing this staff member",
  "adminAuditFlags": ["Flag 1", "Flag 2"]
}`;

return [{
  json: {
    staffId,
    staffName,
    staffType,
    verificationStatus,
    prompt
  }
}];

const geminiResponse = $input.first().json;
const meta = $('Prepare Staff Audit Prompt').first().json;
let parsed = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsed = JSON.parse(rawText);
} catch (err) {
  const isVerified = (meta.verificationStatus === 'VERIFIED');
  parsed = {
    accessVerdict: isVerified ? "PERMIT_ENTRY" : "PROCEED_WITH_WARNING",
    kycComplianceGrade: isVerified ? "FULL_COMPLIANCE" : "PROVISIONAL_GRACE",
    curfewAnomaly: false,
    curfewNotes: "Entry timestamp conforms to standard daylight working schedule.",
    safetyScore: isVerified ? 95 : 65,
    securityOfficerAction: isVerified ? "Verify badge and permit entry." : "Request staff member to submit pending police verification documents to estate office.",
    employerNotice: isVerified ? `Staff member ${meta.staffName} checked in.` : `Staff member ${meta.staffName} has pending police verification. Please assist in uploading Aadhaar/KYC.`,
    adminAuditFlags: isVerified ? [] : ["Pending police verification certificate"]
  };
}

return [{
  json: {
    status: "success",
    auditedAt: new Date().toISOString(),
    staffId: meta.staffId,
    staffName: meta.staffName,
    complianceAudit: parsed
  }
}];
